CREATE DEFINER = `u`@`h` PROCEDURE `p`( IN `a` INT(11), OUT `b` VARCHAR(10), INOUT `c` BIGINT(20)) COMMENT 'c' LANGUAGE SQL NOT DETERMINISTIC CONTAINS SQL SQL SECURITY DEFINER SELECT 1
